package java.math;
public class BigDecimal extends Number implements Comparable<BigDecimal> {
 public static final int ROUND_UP=0,ROUND_DOWN=1,ROUND_CEILING=2,ROUND_FLOOR=3,ROUND_HALF_UP=4,ROUND_HALF_DOWN=5,ROUND_HALF_EVEN=6,ROUND_UNNECESSARY=7;
 public static final BigDecimal ZERO=valueOf(0),ONE=valueOf(1),TEN=valueOf(10);
 private final BigInteger u; private final int s;
 public BigDecimal(BigInteger v){this(v,0);} public BigDecimal(BigInteger v,int scale){if(v==null)throw new NullPointerException();u=v;s=scale;}
 public BigDecimal(int v){this(BigInteger.valueOf(v),0);}public BigDecimal(long v){this(BigInteger.valueOf(v),0);}
 public BigDecimal(double v){
  if(Double.isNaN(v)||Double.isInfinite(v))throw new NumberFormatException("Infinite or NaN");
  long bits=Double.doubleToLongBits(v);int exp=(int)((bits>>>52)&2047);long frac=bits&0xfffffffffffffL;if(exp!=0)frac|=1L<<52;int e=(exp==0?-1022:exp-1023)-52;BigInteger a=BigInteger.valueOf(frac);if((bits<0))a=a.negate();if(a.signum()==0){u=BigInteger.ZERO;s=0;return;}while(e<0&&!a.testBit(0)){a=a.shiftRight(1);e++;}if(e<0){u=a.multiply(BigInteger.valueOf(5).pow(-e));s=-e;}else{u=a.shiftLeft(e);s=0;}
 }
 public BigDecimal(String str){
  int len=str.length(),pos=0;boolean neg=false;if(len==0)throw new NumberFormatException();if(str.charAt(0)=='-'||str.charAt(0)=='+'){neg=str.charAt(0)=='-';pos++;}StringBuilder b=new StringBuilder();int scale=0;boolean dot=false,any=false;while(pos<len){char c=str.charAt(pos);if(c=='e'||c=='E')break;if(c=='.'){if(dot)throw new NumberFormatException();dot=true;}else if(c>='0'&&c<='9'){b.append(c);if(dot)scale++;any=true;}else throw new NumberFormatException();pos++;}if(!any)throw new NumberFormatException();if(pos<len){int e=Integer.parseInt(str.substring(pos+1));long z=(long)scale-e;if(z<Integer.MIN_VALUE||z>Integer.MAX_VALUE)throw new NumberFormatException();scale=(int)z;}BigInteger x=new BigInteger(b.toString());u=neg?x.negate():x;s=scale;
 }
 public static BigDecimal valueOf(long v){return new BigDecimal(v);}public static BigDecimal valueOf(long v,int scale){return new BigDecimal(BigInteger.valueOf(v),scale);}public static BigDecimal valueOf(double v){return new BigDecimal(Double.toString(v));}
 private static BigInteger ten(int n){if(n<0)throw new ArithmeticException("Underflow");return BigInteger.TEN.pow(n);}private static int checked(long n){if(n<Integer.MIN_VALUE||n>Integer.MAX_VALUE)throw new ArithmeticException("Scale out of range");return (int)n;}
 public int scale(){return s;}public int signum(){return u.signum();}public BigInteger unscaledValue(){return u;}public int precision(){return u.abs().toString().length();}
 public BigDecimal add(BigDecimal b){int sc=Math.max(s,b.s);return new BigDecimal(u.multiply(ten(sc-s)).add(b.u.multiply(ten(sc-b.s))),sc);}public BigDecimal subtract(BigDecimal b){return add(b.negate());}public BigDecimal multiply(BigDecimal b){return new BigDecimal(u.multiply(b.u),checked((long)s+b.s));}
 public BigDecimal add(BigDecimal b,MathContext mc){return add(b).round(mc);}public BigDecimal subtract(BigDecimal b,MathContext mc){return subtract(b).round(mc);}public BigDecimal multiply(BigDecimal b,MathContext mc){return multiply(b).round(mc);}
 private static BigInteger rounded(BigInteger a,BigInteger b,RoundingMode m){BigInteger[] qr=a.divideAndRemainder(b);if(qr[1].signum()==0)return qr[0];int sign=a.signum()*b.signum();boolean inc=false;switch(m){case UP:inc=true;break;case DOWN:break;case CEILING:inc=sign>0;break;case FLOOR:inc=sign<0;break;case UNNECESSARY:throw new ArithmeticException("Rounding necessary");default:int c=qr[1].abs().multiply(BigInteger.TWO).compareTo(b.abs());inc=c>0||(c==0&&(m==RoundingMode.HALF_UP||(m==RoundingMode.HALF_EVEN&&qr[0].testBit(0))));}return inc?qr[0].add(BigInteger.valueOf(sign)):qr[0];}
 public BigDecimal divide(BigDecimal b,int scale,RoundingMode mode){int d=checked((long)scale+b.s-s);BigInteger a=u,den=b.u;if(d>=0)a=a.multiply(ten(d));else den=den.multiply(ten(-d));return new BigDecimal(rounded(a,den,mode),scale);}
 public BigDecimal divide(BigDecimal b,RoundingMode mode){return divide(b,s,mode);}public BigDecimal divide(BigDecimal b,int scale,int mode){return divide(b,scale,RoundingMode.valueOf(mode));}public BigDecimal divide(BigDecimal b,int mode){return divide(b,s,RoundingMode.valueOf(mode));}
 public BigDecimal divide(BigDecimal b){if(b.signum()==0)throw new ArithmeticException("Division by zero");BigInteger g=u.gcd(b.u),a=u.divide(g),d=b.u.divide(g);if(d.signum()<0){a=a.negate();d=d.negate();}int twos=0,fives=0;while(d.mod(BigInteger.TWO).signum()==0){d=d.divide(BigInteger.TWO);twos++;}BigInteger five=BigInteger.valueOf(5);while(d.mod(five).signum()==0){d=d.divide(five);fives++;}if(!d.equals(BigInteger.ONE))throw new ArithmeticException("Non-terminating decimal expansion; no exact representable decimal result.");int n=Math.max(twos,fives);a=a.multiply(BigInteger.TWO.pow(n-twos)).multiply(five.pow(n-fives));return new BigDecimal(a,checked((long)s-b.s+n));}
 public BigDecimal divide(BigDecimal b,MathContext mc){int p=mc.getPrecision();if(p==0)return divide(b);if(b.signum()==0)throw new ArithmeticException("Division by zero");try{return divide(b).round(mc);}catch(ArithmeticException ex){if(!"Non-terminating decimal expansion; no exact representable decimal result.".equals(ex.getMessage()))throw ex;}int exp=checked((long)precision()-b.precision()-s+b.s);BigDecimal aa=abs(),bb=b.abs().scaleByPowerOfTen(exp);if(aa.compareTo(bb)<0)exp--;int sc=checked((long)p-1-exp);return divide(b,sc,mc.getRoundingMode()).round(mc);}
 public BigDecimal divideToIntegralValue(BigDecimal b){BigDecimal q=divide(b,0,RoundingMode.DOWN);int preferred=checked((long)s-b.s);if(preferred>0)return q.setScale(preferred);while(q.s>preferred&&q.u.signum()!=0&&q.u.remainder(BigInteger.TEN).signum()==0)q=new BigDecimal(q.u.divide(BigInteger.TEN),q.s-1);if(q.signum()==0&&preferred<0)return new BigDecimal(BigInteger.ZERO,preferred);return q;}
 public BigDecimal remainder(BigDecimal b){return subtract(divideToIntegralValue(b).multiply(b));}public BigDecimal pow(int n){if(n<0)throw new ArithmeticException("Invalid operation");return new BigDecimal(u.pow(n),checked((long)s*n));}
 public BigDecimal negate(){return new BigDecimal(u.negate(),s);}public BigDecimal abs(){return signum()<0?negate():this;}public BigDecimal negate(MathContext mc){return negate().round(mc);}public BigDecimal abs(MathContext mc){return abs().round(mc);}
 public BigDecimal setScale(int n){return setScale(n,RoundingMode.UNNECESSARY);}public BigDecimal setScale(int n,int mode){return setScale(n,RoundingMode.valueOf(mode));}public BigDecimal setScale(int n,RoundingMode mode){int d=checked((long)n-s);return d>=0?new BigDecimal(u.multiply(ten(d)),n):new BigDecimal(rounded(u,ten(-d),mode),n);}
 public BigDecimal round(MathContext mc){int p=mc.getPrecision();if(p==0||precision()<=p)return this;BigDecimal x=setScale(checked((long)s-(precision()-p)),mc.getRoundingMode());if(x.precision()>p)x=x.setScale(x.s-1,mc.getRoundingMode());return x;}
 public BigDecimal stripTrailingZeros(){if(signum()==0)return ZERO;BigInteger x=u;int sc=s;while(x.remainder(BigInteger.TEN).signum()==0){x=x.divide(BigInteger.TEN);sc=checked((long)sc-1);}return new BigDecimal(x,sc);}
 public int compareTo(BigDecimal b){if(signum()!=b.signum())return signum()<b.signum()?-1:1;if(signum()==0)return 0;long ea=(long)precision()-s,eb=(long)b.precision()-b.s;if(ea!=eb)return (ea<eb?-1:1)*signum();int sc=Math.max(s,b.s);return u.multiply(ten(sc-s)).compareTo(b.u.multiply(ten(sc-b.s)));}
 public boolean equals(Object o){return o instanceof BigDecimal&&s==((BigDecimal)o).s&&u.equals(((BigDecimal)o).u);}public int hashCode(){return 31*u.hashCode()+s;}public BigDecimal min(BigDecimal b){return compareTo(b)<=0?this:b;}public BigDecimal max(BigDecimal b){return compareTo(b)>=0?this:b;}
 public BigDecimal scaleByPowerOfTen(int n){return new BigDecimal(u,checked((long)s-n));}public BigDecimal movePointLeft(int n){BigDecimal x=scaleByPowerOfTen(-n);return x.s<0?x.setScale(0):x;}public BigDecimal movePointRight(int n){BigDecimal x=scaleByPowerOfTen(n);return x.s<0?x.setScale(0):x;}
 private static String zeros(int n){StringBuilder b=new StringBuilder();while(n-->0)b.append('0');return b.toString();}
 public String toPlainString(){String d=u.abs().toString(),neg=signum()<0?"-":"";if(s<=0)return neg+d+zeros(-s);int point=d.length()-s;if(point>0)return neg+d.substring(0,point)+"."+d.substring(point);return neg+"0."+zeros(-point)+d;}
 public String toString(){String d=u.abs().toString(),neg=signum()<0?"-":"";long exp=(long)d.length()-1-s;if(s>=0&&exp>=-6)return toPlainString();String mant=d.length()==1?d:d.substring(0,1)+"."+d.substring(1);return neg+mant+"E"+(exp>=0?"+":"")+exp;}
 public String toEngineeringString(){String d=u.abs().toString(),neg=signum()<0?"-":"";long exp=(long)d.length()-1-s;if(s>=0&&exp>=-6)return toPlainString();int rem=(int)((exp%3+3)%3);long e=exp-rem;int before=rem+1;if(signum()==0&&rem!=0){before=1;e+=3;d="0"+zeros(3-rem);}else if(d.length()<before)d+=zeros(before-d.length());String mant=d.length()>before?d.substring(0,before)+"."+d.substring(before):d;return neg+mant+"E"+(e>=0?"+":"")+e;}
 public BigInteger toBigInteger(){return s<=0?u.multiply(ten(-s)):u.divide(ten(s));}public int intValue(){return toBigInteger().intValue();}public long longValue(){return toBigInteger().longValue();}public float floatValue(){return (float)doubleValue();}public double doubleValue(){return Double.parseDouble(toString());}public int intValueExact(){BigInteger x=setScale(0).u;long v=x.longValueExact();if(v<Integer.MIN_VALUE||v>Integer.MAX_VALUE)throw new ArithmeticException("Overflow");return (int)v;}public BigDecimal ulp(){return new BigDecimal(BigInteger.ONE,s);}
}
